Add three more validators in `validators_later.py`, in the same form as the ones in `validators.py`:

- V7 (`entries`): every warehouse's capacity was respected across runs. Each entry: `{"wh": str, "capacity": int, "max_units": int}`.
- V8 (`entries`): all expiries were notified. Each entry: `{"expired": [[sku, wh, qty], ...], "notified": [[sku, wh, qty], ...]}`.
- V9 (`entries`): every supplier's reliability stayed in range. Each entry: `{"supplier": str, "reliability": int}`.

## Repository files

`CONTRIBUTING.md`:

```
# Contributing

- Python 3.11, standard library only.
- Keep functions small and name them after what they check or do.
- Every change comes with tests.
- `vendor/` is read-only; report problems with `ask_owner`.
- Checks: an empty result never passes a check.
```

`validators.py`:

```
"""Validators over depot harness outputs.

Each validator vN(items) returns (passed, measured). An empty input never passes.
"""

from typing import Any

# Notification types emitted by the depot, per the spec:
#   OVERDRAWN (C20), EXPIRY (C13), REORDER (C14),
#   SUPPLIER_SUSPENDED (C17), AUDIT_MISMATCH (C22).
EXPECTED_NOTIFICATION_TYPES = frozenset(
    {"OVERDRAWN", "EXPIRY", "REORDER", "SUPPLIER_SUSPENDED", "AUDIT_MISMATCH"}
)


def _as_list(items: Any) -> list:
    if items is None:
        return []
    try:
        return list(items)
    except TypeError:
        return []


def v1(items):
    """V1 (rows): every report row has value_cents == units * unit_cost.

    Returns (passed, measured) where measured is the list of offending rows.
    """
    rows = _as_list(items)
    if not rows:
        return False, []
    bad = []
    for row in rows:
        try:
            ok = row["value_cents"] == row["units"] * row["unit_cost"]
        except (KeyError, TypeError):
            ok = False
        if not ok:
            bad.append(row)
    return (len(bad) == 0), bad


def v2(items):
    """V2 (runs): every notification type in the spec was seen across the runs.

    Returns (passed, measured) where measured is the sorted list of missing types.
    """
    runs = _as_list(items)
    if not runs:
        return False, sorted(EXPECTED_NOTIFICATION_TYPES)
    seen = set()
    for run in runs:
        for note in _as_list(run):
            if isinstance(note, (tuple, list)) and len(note) > 0:
                seen.add(note[0])
    missing = sorted(EXPECTED_NOTIFICATION_TYPES - seen)
    return (len(missing) == 0), missing


def v3(items):
    """V3 (pairs): two runs with the same seed are identical.

    Returns (passed, measured) where measured is the list of seeds whose runs differ.
    """
    pairs = _as_list(items)
    if not pairs:
        return False, []
    differing = []
    for pair in pairs:
        try:
            same = pair["a"] == pair["b"]
            seed = pair["seed"]
        except (KeyError, TypeError):
            differing.append(None)
            continue
        if not same:
            differing.append(seed)
    return (len(differing) == 0), differing


def v4(items):
    """V4 (days): storage cost stayed within budget each day.

    Returns (passed, measured) where measured is the list of over-budget days.
    """
    days = _as_list(items)
    if not days:
        return False, []
    over = []
    for d in days:
        try:
            within = d["storage_cost_cents"] <= d["budget_cents"]
            day = d["day"]
        except (KeyError, TypeError):
            over.append(None)
            continue
        if not within:
            over.append(day)
    return (len(over) == 0), over


def v5(items):
    """V5 (clauses): every clause has at least one test.

    A test is a non-empty string. Returns (passed, measured) where measured is
    the list of clause ids with no tests.
    """
    clauses = _as_list(items)
    if not clauses:
        return False, []
    untested = []
    for c in clauses:
        try:
            tests = [t for t in c["tests"] if isinstance(t, str) and t.strip()]
            cid = c["clause_id"]
        except (KeyError, TypeError):
            untested.append(None)
            continue
        if not tests:
            untested.append(cid)
    return (len(untested) == 0), untested


def v6(items):
    """V6 (pairs): two implementations agree on every compared pair.

    Returns (passed, measured) where measured is the list of keys that disagree.
    """
    pairs = _as_list(items)
    if not pairs:
        return False, []
    disagree = []
    for p in pairs:
        try:
            same = p["a"] == p["b"]
            key = p["key"]
        except (KeyError, TypeError):
            disagree.append(None)
            continue
        if not same:
            disagree.append(key)
    return (len(disagree) == 0), disagree
